// Gabarito comentado — penal (gerado). Chave: chaveQ(enunciado) em leitura/index.js.
export default {"aplicacao":{"j8s6a0":["É o art. 4º do CP (teoria da atividade).",""],"815uw7":["Pelo art. 2º, parágrafo único, do CP e pelo art. 5º, XL, da CF, a lei mais benéfica retroage SEMPRE, até mesmo depois do trânsito em julgado. Nesse caso, quem aplica é o juízo da execução (Súmula 611 do STF).",""],"5ciol7":["É a abolitio criminis (CP, art. 2º): a lei nova descriminaliza o fato, e isso apaga a execução e os efeitos penais da condenação (reincidência, por exemplo). É causa de extinção da punibilidade (art. 107, III).",""],"1ip58yp":["A obrigação de indenizar o dano continua, porque o fato continua sendo ilícito civil. Só os efeitos penais desaparecem.",""],"1fr4myc":["É a novatio legis in mellius (CP, art. 2º, parágrafo único): retroage mesmo com trânsito em julgado.",""],"1u0uvns":["É o art. 3º do CP: essas leis são ultrativas, ou seja, continuam valendo para os fatos praticados durante sua vigência, mesmo depois que deixam de vigorar. Se não fosse assim, bastaria atrasar o processo para escapar da punição.",""],"1ajed5e":["É o art. 6º do CP: o crime é considerado praticado tanto onde ocorreu a conduta quanto onde ocorreu (ou deveria ocorrer) o resultado. Serve para os crimes à distância, que envolvem mais de um país.",""],"1yqf2fx":["L-U: Lugar = Ubiquidade. T-A: Tempo = Atividade.",""],"blmf3g":["É o art. 5º do CP: territorialidade temperada (ou mitigada), porque tratados podem afastar a lei brasileira, como no caso de diplomatas.",""],"1s8xb0v":["É o art. 5º, §1º: navios e aviões públicos ou a serviço do governo brasileiro são território brasileiro onde estiverem, até em porto ou espaço aéreo estrangeiro.",""],"ma3cw5":["É o art. 5º, §1º, parte final: as privadas só são território brasileiro em alto-mar ou no espaço aéreo correspondente. Em porto estrangeiro, vale a lei do país.",""],"skcmaw":["É o art. 5º, §2º: aeronave ou navio estrangeiro privado em território brasileiro (pousado, ancorado ou no espaço aéreo) segue a lei brasileira.",""],"woq1fj":["É o art. 7º, I, a, do CP: extraterritorialidade incondicionada. A lei brasileira se aplica sem nenhuma condição.",""],"jmo59w":["É o art. 7º, I, b: inclui também empresas públicas, sociedades de economia mista, autarquias e fundações públicas.",""],"z43cj4":["É o art. 7º, I, c: extraterritorialidade incondicionada.",""],"g8arzz":["É o art. 7º, I, d: extraterritorialidade incondicionada.","Incondicionada (art. 7º, I): Presidente, patrimônio/fé pública, administração pública, genocídio. Macete “PPAG”."],"utm6dm":["É o art. 7º, §1º: não importa o que aconteceu no estrangeiro. Para evitar punição dupla, a pena cumprida lá é descontada (art. 8º).",""],"23r8za":["É o art. 8º do CP: se as penas forem da mesma espécie, desconta-se (computa); se forem diferentes, a pena brasileira é atenuada.",""],"urrw63":["É o art. 7º, II, a: extraterritorialidade condicionada (exemplo: tráfico internacional de pessoas).",""],"17mdw7t":["É o art. 7º, II, b: também condicionada. Os outros casos são os crimes em aeronaves e navios brasileiros privados em território estrangeiro não julgados lá (II, c).",""],"f7qtvy":["É o art. 7º, §2º: entrar no Brasil, o fato ser crime também no outro país, estar entre os crimes que admitem extradição, não ter sido absolvido ou cumprido pena lá e não ter sido perdoado ou extinta a punibilidade.",""],"1wdw9x":["É o art. 10 do CP: no prazo penal (de pena, prescrição, decadência), o dia do começo conta. Os dias, meses e anos seguem o calendário comum.","Prazo penal (CP, art. 10): inclui o começo. Prazo processual (CPP, art. 798): exclui o começo."],"mplufm":["No prazo penal, o dia do começo é incluído (art. 10). Quem exclui é o prazo processual.",""],"12n0gfd":["É o art. 11 do CP: pena de 10 dias e meio vira 10 dias. Na multa, desprezam-se as frações de moeda.",""],"6uxh79":["É o art. 12 do CP: princípio da especialidade. A Parte Geral do CP vale para as leis especiais, salvo se elas trouxerem regra própria.",""],"17frv29":["É o art. 5º, XL, da CF: a lei penal só retroage para beneficiar o réu.",""],"trr7i0":["É a Súmula 711 do STF: no crime permanente (como o sequestro), o crime está sendo cometido enquanto dura. Se a lei mais grave entra em vigor antes de acabar a permanência, ela se aplica, sem que isso seja retroatividade.",""],"1e0m6xx":["É a Súmula 711 do STF, que vale também para o crime continuado.",""],"1t3psqm":["É a Súmula 611 do STF.",""],"1dmy4su":["É a Súmula 501 do STJ: o juiz aplica a lei antiga OU a nova, a que for mais benéfica no todo, mas não pode misturar pedaços das duas (isso criaria uma terceira lei).",""],"1eta8c9":["O art. 5º traz a regra (crime no Brasil, lei brasileira). O art. 7º traz as exceções (crime no exterior, lei brasileira).",""],"og71dn":["É a Convenção de Viena sobre Relações Diplomáticas (1961): o diplomata responde pela lei do seu país. É exemplo da territorialidade “temperada” por tratados.",""],"1b7ogd4":["Atividade (art. 4º).","",["Ubiquidade é para o lugar.","Correta.","O resultado não define o tempo.","Mista é a ubiquidade.","Territorialidade é sobre o espaço."]],"1dfwq54":["Ubiquidade (art. 6º).","",["Atividade é para o tempo.","O resultado sozinho não basta.","Correta.","Domicílio não é o critério.","Nacionalidade é personalidade."]],"2p2xy3":["Abolitio criminis (art. 2º).","",["É a lei nova mais grave.","Correta.","Lex gravior é a lei mais grave.","Ultratividade é a lei que continua valendo após revogada.","Lei temporária tem prazo certo."]],"lfu7ty":["Ultrativa (art. 3º).","",["Retroatividade é olhar para trás.","Correta.","É constitucional.","Não abole crimes.","Não é o termo."]],"1kjwxcb":["A vida ou liberdade do Presidente da República (art. 7º, I, a).","",["É condicionada.","Correta.","Segue a territorialidade.","É condicionada.","Não está no art. 7º, I."]],"1mafvgy":["É incluído (art. 10).","",["É no processual.","Correta.","Não depende da pena.","Não é em dobro.","Não depende de dia útil."]],"10ngab4":["Aplica-se a lei mais grave (Súmula 711).","",["Aplica-se a nova.","Correta.","Não há abolitio.","Não há média.","O crime não se extingue."]],"1jr8vh3":["Juízo das execuções (Súmula 611).","",["Não ao STF.","Correta.","Não ao tribunal da condenação.","O MP não aplica.","O delegado não aplica."]],"jtlbnw":["É vedada (Súmula 501).","",["É proibida.","Correta.","Não é faculdade.","A súmula nasceu do tráfico, mas vale em geral.","Não depende do MP."]],"zqbbpe":["Extensão do território nacional (art. 5º, §1º).","",["Navio público é território brasileiro.","Correta.","Não é área internacional.","Não segue o porto.","Não é zona neutra."]],"1ps5rto":["Civis.","",["Os penais são afastados.","Correta.","A reincidência é efeito penal e cai.","A execução cessa.","A pena cai."]],"10qyfcp":["Ter o agente bens no Brasil.","",["É condição.","É condição.","É condição.","É condição.","Correta."]],"giyrzz":["Desprezadas (art. 11).","",["Não são contadas.","Correta.","Não são arredondadas.","Não viram multa.","Não são dobradas."]],"194b0yp":["Aplica-se a lei brasileira (art. 5º, §2º).","",["Aplica-se.","Correta.","A lei brasileira prevalece.","Há lei aplicável.","A lei brasileira se aplica."]],"huvo9j":["Territorialidade (art. 5º).","",["É exceção.","Correta.","Universalidade é para crimes de tratado.","Personalidade é pela nacionalidade.","Representação é para navios e aviões privados."]],"nflpfm":["Lugar = Ubiquidade; Tempo = Atividade.","",["Está invertido.","Correta.","Não é isso.","Tem relação.","Não é isso."]],"1lylsgo":["Aos fatos anteriores, mesmo com sentença transitada em julgado (art. 2º, parágrafo único).","",["Retroage.","Correta.","Vale a qualquer tempo.","É obrigatória.","Aplica-se."]],"5gpb5f":["É a Súmula 611 do STF.",""],"qwa0cr":["A Súmula 501 do STJ veda: aplica-se integralmente a lei antiga ou a nova, a que for mais favorável no caso.",""],"1o3tgv6":["É a Súmula 711 do STF.",""]},"culpabilidade":{"1xik4ie":["É o art. 28, §1º, do CP: se a pessoa se embriagou sem querer (por exemplo, alguém colocou droga na bebida) e ficou totalmente incapaz de entender o que fazia, ela é isenta de pena. A embriaguez voluntária ou culposa nunca isenta.","Voluntária ou culposa = não isenta. Caso fortuito completa = isenta. Caso fortuito incompleta = reduz de 1/3 a 2/3."],"13dk81r":["Pelo art. 21 do CP, só o erro de proibição INEVITÁVEL isenta de pena. O evitável (o agente podia saber que a conduta era proibida) apenas diminui a pena de 1/6 a 1/3.",""],"psoq2p":["Pela teoria normativa pura (finalista), a culpabilidade é um juízo de reprovação com três elementos: imputabilidade, potencial consciência da ilicitude e exigibilidade de conduta diversa. Dolo e culpa ficam no fato típico.","Macete “IPE”: Imputabilidade, Potencial consciência, Exigibilidade."],"2dnc7r":["É o art. 26 do CP: o inimputável por doença mental recebe absolvição imprópria e medida de segurança.",""],"6geez9":["É preciso a causa biológica (doença mental) E o efeito psicológico (incapacidade de entender ou de se controlar no momento do crime). A doença sozinha não basta.",""],"1q9dc1a":["É o art. 26, parágrafo único: o semi-imputável é condenado com pena reduzida de 1/3 a 2/3, ou o juiz pode substituir a pena por medida de segurança (art. 98).",""],"61bwac":["É o art. 27 do CP e o art. 228 da CF: o menor responde por ato infracional, conforme o ECA.",""],"14ygevq":["Basta a idade: o menor de 18 anos é inimputável, sem perguntar se entendia ou não o que fazia (presunção absoluta).",""],"xa9xgc":["É o art. 28, I, do CP. A emoção pode, no máximo, atenuar a pena ou gerar o homicídio privilegiado (violenta emoção).",""],"14u687t":["É o art. 28, II. Pela teoria da actio libera in causa, a imputabilidade é avaliada no momento em que a pessoa decidiu beber, quando era livre.",""],"1q01vjf":["É o art. 28, §1º.",""],"e4hcer":["É o art. 61, II, l: além de não excluir a imputabilidade, a embriaguez preordenada agrava a pena. Exemplo: beber para criar coragem de matar.",""],"gzaac8":["É o art. 21 do CP: ninguém se livra dizendo que não conhecia a lei. O desconhecimento é, no máximo, atenuante (art. 65, II). Diferente disso é o erro de proibição (achar que a conduta é permitida).",""],"1jhpfzz":["É o art. 21 do CP (erro de proibição).",""],"1844vs8":["É o art. 21, parágrafo único: se nas circunstâncias o agente podia saber que era proibido, o erro é evitável.",""],"1pg8sm7":["É o art. 22 do CP: quem coagiu ou deu a ordem responde pelo crime. O coagido ou o subordinado fica isento por inexigibilidade de conduta diversa.",""],"f2ipvz":["Na coação moral (ameaça grave), a pessoa age com vontade, mas não se pode exigir que aja de outro modo. Exemplo: o gerente obrigado a abrir o cofre porque a família está sob ameaça.",""],"peyrup":["Na coação física (vis absoluta), não há vontade: o agente é usado como instrumento. Sem conduta, não há fato típico.","Coação física = exclui a conduta (fato atípico). Coação moral = exclui a culpabilidade."],"12etkjl":["A hierarquia do art. 22 é a do serviço público (servidor e chefe). Empregado de empresa privada e filho em relação aos pais não se encaixam.",""],"firj3g":["Se a ilegalidade é evidente, o subordinado tinha o dever de recusar. Ele responde junto com o superior, podendo ter pena atenuada (art. 65, III, c).",""],"1in6sny":["Não exclui (art. 28, II). Aplica-se a actio libera in causa.",""],"2m23qk":["O evitável só diminui a pena de 1/6 a 1/3 (art. 21).",""],"1hgk5lh":["É o art. 97 do CP: o juiz absolve, mas aplica medida de segurança (internação ou tratamento ambulatorial). Por isso se chama absolvição imprópria.",""],"rn78op":["É o art. 97, §1º: prazo mínimo de 1 a 3 anos, e dura enquanto não cessar a periculosidade, verificada por perícia.",""],"1kgrx7g":["É a Súmula 527 do STJ: a medida não pode durar mais que a pena máxima prevista para o crime.",""],"1ifdb8k":["Para o STJ, a pessoa é imputável a partir do primeiro minuto do dia do 18º aniversário, sem contar horas.",""],"gg7ire":["É o ECA (Lei 8.069/1990): o adolescente recebe medida socioeducativa; a criança, medida de proteção.",""],"1y9a7q1":["Pela teoria tripartida, crime é fato típico, ilícito e culpável. A culpabilidade é o juízo de que o autor merece reprovação.",""],"164btj3":["O agente sabe que a conduta é proibida em geral, mas pensa que está autorizado no caso. Exemplo: achar que pode agredir quem o ofendeu “em legítima defesa da honra”. Segue o art. 21.",""],"e2qdhm":["São os §§1º e 2º do art. 28: completa = isenta; incompleta (capacidade só diminuída) = reduz de 1/3 a 2/3.",""],"zfw7y5":["Atenuante: crime sob influência de violenta emoção provocada por ato injusto da vítima (art. 65, III, c). Diminuição: homicídio sob o domínio de violenta emoção logo após injusta provocação (art. 121, §1º).",""],"1yacbg8":["Basta que o agente possa saber, como leigo, que a conduta é errada ou proibida.",""],"1g43xh5":["Além da coação moral e da obediência hierárquica (art. 22), a doutrina admite a inexigibilidade como causa supralegal, para situações extremas não previstas em lei.",""],"6thcdz":["Dolo: no finalismo, o dolo integra o fato típico.","",["É elemento.","É elemento.","É elemento.","Correta.","O dolo não é."]],"19k8wqx":["Biológico (art. 27).","",["Psicológico é avaliar o entendimento.","Correta.","Biopsicológico é o da doença mental.","Não é social.","Não é econômico."]],"1lct2oa":["Completa por caso fortuito ou força maior (art. 28, §1º).","",["Não exclui.","Não exclui.","Correta.","Agrava.","Não exclui."]],"33jzeu":["Isenta de pena (art. 21).","",["Quem diminui é o evitável.","Correta.","Não agrava.","É relevante.","Excluir o dolo é o erro de tipo."]],"n7t4uh":["1/6 a 1/3 (art. 21).","",["1/3 a 2/3 é a semi-imputabilidade.","Correta.","Não é metade.","Não é 2/3.","Reduz."]],"1bn0i1f":["Culpabilidade.","",["Há conduta típica.","O fato continua ilícito.","Correta.","Não é causa de extinção da punibilidade.","Há vontade, logo há conduta."]],"11ov1ix":["Conduta.","",["É a moral que exclui a culpabilidade.","Correta.","Não é excludente de ilicitude.","Não é causa de extinção da punibilidade.","Exclui antes, a própria conduta."]],"19ol19g":["Redução da pena de 1/3 a 2/3 (art. 26, parágrafo único).","",["Isenção é para o inimputável.","Correta.","Não aumenta.","Não há absolvição.","Não há arquivamento."]],"1ebm8g4":["Não excluem a imputabilidade (art. 28, I).","",["Não excluem.","Correta.","Não isentam.","Não mudam o dolo.","Não anulam nada."]],"ui0y64":["É inescusável (art. 21).","",["Não isenta.","Correta.","Não exclui o dolo.","Não absolve.","É só atenuante."]],"1ta8ohe":["Não isenta o subordinado (art. 22).","",["Só a ordem não manifestamente ilegal isenta.","Correta.","Não exclui a tipicidade.","Não é legítima defesa.","Não é exercício regular de direito."]],"1htm83p":["Circunstância agravante (art. 61, II, l).","",["Não exclui.","Correta.","Não atenua.","É relevante.","Não absolve."]],"1wvqb45":["O máximo da pena abstrata do crime (Súmula 527).","",["Não há limite fixo de 10 anos.","Correta.","Não é 30 anos fixos.","1 ano é parte do prazo mínimo.","A idade não é o limite."]],"1qd3isv":["Absolvição imprópria com medida de segurança (arts. 26 e 97).","",["Pena reduzida é para o semi-imputável.","Correta.","Não recebe pena.","Não é perdão judicial.","Não é multa."]],"qn9fq6":["Embriaguez voluntária ou culposa (art. 28, II).","",["A coação isenta.","Correta.","A menoridade é critério biológico.","A doença mental isenta.","A obediência pode isentar."]],"1581pul":["Ato infracional (ECA).","",["Não comete crime.","Correta.","Não é contravenção.","Há consequência no ECA.","Não é crime."]],"1hkbz4f":["Direito público.","",["Relação privada não serve.","Correta.","Parentesco não serve.","Emprego privado não serve.","Amizade não serve."]],"yz8wz6":["É o art. 61, II, l, do CP.",""],"n2aay5":["A imputabilidade é avaliada no momento ANTERIOR, quando o agente, ainda livre, decidiu se embriagar (a causa foi livre). Por isso ele responde mesmo estando embriagado na hora do crime.",""]},"fe-administracao":{"1yyfuam":["É a Súmula 522 do STJ: mentir o nome para a polícia é crime de falsa identidade (CP, art. 307), mesmo que a pessoa diga que fez isso para se defender. O direito de não se autoincriminar permite ficar calado, mas não permite mentir a identidade.",""],"17n0xnz":["EXIGIR é concussão (art. 316): o funcionário impõe a vantagem, e a vítima cede por medo. Corrupção passiva (art. 317) é solicitar, receber ou aceitar promessa de vantagem.","Exigir = concussão. Solicitar, receber, aceitar promessa = corrupção passiva. Oferecer ou prometer (particular) = corrupção ativa."],"1a95l04":["É o art. 289 do CP: reclusão de 3 a 12 anos e multa. O crime protege a fé pública, e a competência, em regra, é da Justiça Federal.",""],"m437b5":["É o art. 289, §2º: forma privilegiada, com detenção de 6 meses a 2 anos e multa. A pessoa foi enganada e, ao descobrir, tentou passar o prejuízo adiante.",""],"u2hpcv":["Se a falsificação é grosseira, a cédula não engana o público em geral e não ofende a fé pública. Se enganou alguém em particular, há estelionato, da Justiça Estadual.",""],"k1m7ju":["É o art. 297 do CP: falsidade material de documento público, com reclusão de 2 a 6 anos e multa. Se o agente é funcionário público e se aproveita do cargo, a pena aumenta de 1/6.",""],"12yrdu5":["É o art. 297, §2º: também se equiparam o documento de entidade paraestatal, o título ao portador ou transmissível por endosso, as ações de sociedade comercial e os livros mercantis.",""],"1tmx1p2":["É o art. 298, parágrafo único (incluído pela Lei 12.737/2012).",""],"hbsbc4":["É o art. 299 do CP: o papel é verdadeiro (emitido por quem devia emitir), mas a informação inserida é falsa. Exemplo: declarar dados falsos numa certidão.","Material = a forma é falsa (o documento foi fabricado ou adulterado). Ideológica = a forma é verdadeira, o conteúdo é falso."],"wk8y9l":["Essa é a definição da falsidade ideológica. Na material, o próprio documento é falsificado ou alterado (exemplo: uma CNH fabricada).",""],"o7z76c":["É o art. 304 do CP. Se o próprio falsificador usa o documento, responde só pela falsificação (o uso é exaurimento).",""],"mqzsnz":["É a Súmula 522 do STJ.",""],"kci6sw":["É o art. 311-A do CP (fraudes em certames de interesse público): reclusão de 1 a 4 anos e multa. Vale para concursos, vestibulares, ENEM e exames da lei.",""],"jqw5zb":["É o art. 327 do CP: o conceito penal é amplo e inclui mesários, jurados e estagiários no exercício da função.",""],"1hdk9p5":["É o art. 327, §1º: também quem exerce cargo em entidade paraestatal.",""],"1fud47o":["É o art. 327, §2º: o aumento alcança ocupantes de cargo em comissão ou função de direção ou assessoramento em órgão da administração direta, sociedade de economia mista, empresa pública ou fundação instituída pelo poder público.",""],"38rx78":["É o art. 312 do CP.",""],"1agl4xp":["É o peculato-furto (art. 312, §1º): o funcionário não tem a posse, mas usa a facilidade do cargo para subtrair ou ajudar alguém a subtrair.",""],"1xg3wgt":["É o art. 312, §3º: o peculato culposo ocorre quando o funcionário, por descuido, permite que outro cometa o crime. Se reparar antes do trânsito em julgado, extingue a punibilidade; se depois, a pena cai pela metade.",""],"mzssnu":["O benefício do §3º vale só para o peculato CULPOSO. No doloso, a reparação pode, no máximo, gerar arrependimento posterior (art. 16) ou atenuante.",""],"aervcw":["É o art. 312, §3º, parte final: a pena imposta é reduzida de metade.",""],"17kpr4h":["É o art. 316 do CP: a pena é de reclusão de 2 a 12 anos e multa (aumentada pelo Pacote Anticrime). O funcionário pode estar até fora da função ou antes de assumi-la, desde que a exigência seja em razão dela.",""],"1pwgcd4":["O crime se consuma no momento da exigência. Receber a vantagem é só exaurimento. Por isso, o flagrante no momento da entrega do dinheiro, em regra, ocorre depois da consumação.",""],"j7ksbt":["Exigir é concussão. Na corrupção passiva, os verbos são solicitar, receber ou aceitar promessa (art. 317).",""],"1d6uzmu":["É o art. 317 do CP. Se, por causa da vantagem, o funcionário retarda, deixa de praticar ou pratica ato infringindo dever funcional, a pena aumenta de 1/3 (§1º).",""],"16ggl6o":["É o art. 317, §2º: não há vantagem; o funcionário cede a pedido ou influência de alguém. A pena é de detenção de 3 meses a 1 ano, ou multa.",""],"1a4sgj2":["É o art. 333 do CP: é crime do particular, com pena de 2 a 12 anos. Se o particular apenas paga uma vantagem que o funcionário exigiu, ele é vítima de concussão, e não comete corrupção ativa.",""],"eqpgv1":["Os crimes são independentes. Se o funcionário solicita e o particular recusa, há só corrupção passiva. Se o particular oferece e o funcionário recusa, há só corrupção ativa.",""],"1h6mwyz":["É o art. 319 do CP: o que caracteriza é o motivo pessoal (interesse ou sentimento), e não dinheiro. Exemplo: o agente não multa o amigo.",""],"fctz5y":["É o art. 320 do CP (condescendência criminosa): também comete quem, sem competência para punir, não leva o fato ao conhecimento de quem tem.",""],"zq4jyh":["É o art. 321 do CP (advocacia administrativa): o funcionário usa sua posição para defender interesse de um particular dentro da Administração, mesmo que o interesse seja legítimo.",""],"3iutqw":["É o art. 325 do CP (violação de sigilo funcional).",""],"76jjb":["É o art. 329 do CP (resistência). Se, por causa da resistência, o ato não é executado, a pena é maior (§1º).","Com violência ou ameaça = resistência. Sem violência, só não obedecendo = desobediência."],"98tiuw":["É o art. 330 do CP. Se a lei já prevê sanção administrativa para o descumprimento e não ressalva a punição penal, a jurisprudência tende a afastar o crime.",""],"1x6wuie":["É o art. 331 do CP. Na ADPF 496, o STF considerou o crime compatível com a CF e com a liberdade de expressão.",""],"1035dlh":["É a Súmula 599 do STJ: nos crimes contra a Administração Pública, protege-se também a moralidade, e por isso não se aplica a insignificância. A exceção é o descaminho, em que se aceita até o limite usado para não cobrar o tributo.",""],"1wd35hc":["É o art. 334 do CP: a mercadoria é permitida, mas entra ou sai sem pagar o imposto.",""],"85ccnz":["É o art. 334-A do CP: a mercadoria em si é proibida (como cigarros sem registro).","Mercadoria permitida sem imposto = descaminho. Mercadoria proibida = contrabando."],"xggchm":["É o art. 339 do CP (denunciação caluniosa): o agente sabe que a pessoa é inocente e provoca uma investigação ou processo contra ela.",""],"1ihvs8r":["É o art. 342, §2º: a retratação antes da sentença no processo em que mentiu extingue a punibilidade.",""],"18ebwia":["É o art. 348, §2º: quem esconde o criminoso por ser parente próximo é isento de pena (escusa absolutória).",""],"ii1ygb":["É o art. 345 do CP: mesmo tendo razão, a pessoa deve recorrer à Justiça. Exemplo: tomar à força o celular de quem deve dinheiro.",""],"8yo5w1":["Concussão (art. 316).","",["Corrupção passiva é solicitar ou receber.","Correta.","Prevaricação é por interesse pessoal, sem vantagem exigida.","Peculato é apropriar-se de bem.","Advocacia administrativa é patrocinar interesse privado."]],"12ymhk1":["Corrupção passiva (art. 317).","",["Concussão é exigir.","Correta.","A ativa é do particular.","Tráfico de influência é do particular que diz influir.","Excesso de exação é cobrar tributo indevido."]],"f2vtrq":["Corrupção ativa (art. 333).","",["A passiva é do funcionário.","Correta.","Concussão é exigir.","Prevaricação é do funcionário.","Advocacia administrativa é do funcionário."]],"fi72kt":["Peculato (art. 312), na modalidade apropriação.","",["Furto não exige a qualidade de funcionário.","Correta.","Apropriação indébita é do particular.","Concussão é exigir.","Estelionato é enganar."]],"1wmob1n":["Prevaricação (art. 319).","",["Correta.","Condescendência é não punir subordinado.","Privilegiada é ceder a pedido de outrem.","Concussão é exigir vantagem.","Abandono é deixar o cargo."]],"1fu77p4":["Peculato culposo (art. 312, §3º).","",["Não vale para o doloso.","Correta.","É doloso.","É doloso.","Não há essa previsão."]],"13j2l3f":["Falsidade ideológica (art. 299).","",["Na material, a forma é falsa.","Correta.","O uso é outro crime.","Falsa identidade é atribuir-se identidade falsa.","Moeda falsa é outro crime."]],"1sw8meb":["Estelionato, da Justiça Estadual.","",["A falsificação grosseira não ofende a fé pública.","Correta.","Não é ideológica.","Se enganou alguém, há estelionato.","Não é contravenção."]],"exo0cg":["Resistência (art. 329).","",["Desobediência é sem violência.","Desacato é ofender.","Correta.","Coação no curso do processo é ameaça em processo.","Exercício arbitrário é fazer justiça com as próprias mãos."]],"3tt6yd":["Contrabando (art. 334-A).","",["Descaminho é mercadoria permitida sem imposto.","Correta.","Facilitação é do funcionário.","Receptação é adquirir produto de crime.","Estelionato é enganar."]],"1e68ioz":["É a Súmula 546 do STJ: o que importa é o órgão a quem o documento foi apresentado. Exemplo: CNH falsa (emitida pelo Detran) apresentada à PRF é crime federal.",""],"jvj2pv":["Pela Súmula 73 do STJ, é, em tese, estelionato, da Justiça Estadual.",""],"126appb":["É a ADPF 496 (2020).",""]},"ilicitude":{"1lwjzy5":["É o art. 24, §1º.",""],"13gvmk7":["O art. 25 exige agressão ATUAL (acontecendo) ou IMINENTE (prestes a acontecer). Contra agressão futura ou já terminada, não há legítima defesa, e sim vingança ou crime preventivo.",""],"7uni7":["É o art. 23 do CP: as quatro excludentes de ilicitude. O fato é típico, mas lícito, porque a lei autoriza.","Excludentes de ilicitude (art. 23): estado de necessidade, legítima defesa, estrito cumprimento do dever legal e exercício regular de direito."],"1qog6ug":["É o art. 23, parágrafo único: quem passa do necessário responde pelo excesso. Exemplo: continuar batendo no agressor já desacordado.",""],"1yo1rio":["É o art. 24 do CP: perigo atual, não provocado voluntariamente pelo agente, inevitável de outro modo, para salvar direito próprio ou alheio, quando não era razoável exigir o sacrifício.",""],"i21hq3":["É o art. 24, §2º: se o bem salvo vale menos que o sacrificado, não há excludente, mas a pena pode ser reduzida de 1/3 a 2/3.",""],"aa5hku":["É o art. 25: agressão injusta, atual ou iminente, a direito próprio ou de outro, repelida com os meios necessários usados com moderação.",""],"15ctjq8":["É o art. 25, parágrafo único (Pacote Anticrime): o policial que age para salvar refém está em legítima defesa, desde que observados os requisitos do caput.",""],"w965re":["O estado de necessidade exige PERIGO atual (que pode vir da natureza, de animal ou de pessoa). Agressão injusta é requisito da legítima defesa.","Legítima defesa = agressão humana injusta. Estado de necessidade = perigo (qualquer origem)."],"df8943":["O art. 25 fala em “direito seu ou de outrem”: pode-se defender um terceiro.",""],"pn70mp":["É o art. 25: só agressão atual ou iminente.",""],"1pc4bgu":["Quem se defendia passou dos limites; a partir daí, o primeiro agressor pode se defender do excesso.",""],"3bxs2a":["Se um age em legítima defesa real, a agressão dele é justa. Contra agressão justa não cabe legítima defesa.",""],"ztomtp":["Quem age em legítima defesa putativa (imaginária) está, de fato, agredindo injustamente o outro, que pode se defender de verdade.",""],"1vbszyj":["É o art. 23, III: o policial tem o dever de prender quem está em flagrante (CPP, art. 301). Usar a força necessária é cumprir o dever.",""],"13bvf3c":["São exemplos clássicos de exercício regular de direito: a atividade é permitida pelo ordenamento e praticada dentro das regras.",""],"14vw916":["O art. 301 do CPP diz que qualquer do povo “poderá” prender: é um direito, e não dever. Por isso é exercício regular de direito, e não estrito cumprimento de dever legal.",""],"18dxamz":["É causa supralegal (não está no CP): bem disponível (como o patrimônio), ofendido capaz e consentimento anterior ou simultâneo à conduta. Não vale para a vida.",""],"1lnxt6f":["É o art. 23, parágrafo único.",""],"hxxq1r":["É o art. 24: quem provocou o perigo de propósito não pode invocar a excludente.",""],"zt82yl":["É o art. 24, §1º.",""],"1cz51mw":["É o art. 20, §1º: o agente acredita, por erro, que está sendo agredido. Se o erro é justificável, fica isento de pena; se não, responde por culpa, se houver forma culposa.",""],"1j0l9nf":["Ofendículos são aparatos para defender o patrimônio (cerca elétrica, cacos de vidro). Parte da doutrina vê exercício regular de direito; outra, legítima defesa preordenada. Devem ser visíveis e proporcionais.",""],"rz4760":["Pela teoria unitária, adotada pelo CP, o estado de necessidade sempre exclui a ilicitude quando o bem salvo vale mais ou igual ao sacrificado. Se vale menos, cabe só a redução do §2º.",""],"12s2044":["O CP só conhece o estado de necessidade justificante. A teoria diferenciadora (que também admite o exculpante) é adotada pelo Código Penal Militar.",""],"1r5p9x1":["Se o dono atiça o cão, o animal é instrumento de uma agressão humana injusta: cabe legítima defesa.",""],"vxmg4":["Sem ser humano por trás, não há agressão injusta, mas há perigo atual. Cabe estado de necessidade.",""],"em6dab":["É o art. 65 do CPP: reconhecida no processo penal a legítima defesa (ou outra excludente), a vítima não pode pedir indenização a quem agiu licitamente, salvo exceções (como terceiro inocente atingido).",""],"16qen88":["O art. 25 exige uso MODERADO dos meios NECESSÁRIOS. Além disso, é excesso.",""],"1y7agh6":["O art. 24 exige que o perigo não tenha sido provocado pela vontade do agente.",""],"1g9fbgl":["A excludente só cobre a atuação dentro dos limites da lei. Excessos podem configurar crime e abuso de autoridade.",""],"96bqg1":["Na ADPF 779, o STF declarou inconstitucional a tese da legítima defesa da honra, que não pode ser usada nem perante o Júri.",""],"1byglhy":["Coação moral irresistível: exclui a culpabilidade (art. 22).","",["É excludente.","É excludente.","É excludente.","É excludente.","Correta."]],"15al4kj":["Injusta, atual ou iminente (art. 25).","",["Futura não.","Passada não.","Correta.","Contra agressão justa não cabe.","Pode ser contra qualquer bem jurídico."]],"955mvx":["Perigo atual não provocado voluntariamente (art. 24).","",["Agressão injusta é da legítima defesa.","Correta.","Quem tem dever legal não pode alegar.","Ordem superior é obediência hierárquica.","Consentimento é outra causa."]],"1qzao1y":["Doloso ou culposo (art. 23, parágrafo único).","",["Responde.","Correta.","Também o culposo.","Também o doloso.","Não há essa condição."]],"1r7qa9a":["Legítima defesa (art. 25, parágrafo único).","",["A lei fala em legítima defesa.","Correta.","Não é exercício de direito.","Não há coação.","O fato é lícito."]],"16e0h59":["Exercício regular de direito.","",["Não há agressão.","Correta.","O médico não tem dever legal de operar.","Não é emergência.","Não há crime."]],"1ar56ea":["Não pode alegar estado de necessidade (art. 24, §1º).","",["É o contrário.","Correta.","Não pode fugir do dever.","Não há agressão.","Não é isento."]],"6qsmgw":["Sucessiva.","",["Putativa é imaginária.","Correta.","Recíproca (real contra real) não existe.","Não é o termo.","Não existe legítima defesa antecipada."]],"1w0z4ll":["Estado de necessidade.","",["Sem agressão humana, não há legítima defesa.","Correta.","Não é exercício de direito.","O fato é lícito.","Não é dever legal."]],"1hdvfqy":["Legítima defesa da honra.","",["A real continua válida.","Correta.","Continua válido.","Continuam válidas.","Não tem relação."]],"2qroka":["Legítima defesa real.","",["Contra a putativa é admitida.","Correta.","É exatamente o caso de legítima defesa.","É admitida.","Contra o excesso é admitida (sucessiva)."]],"adjerw":["Faz coisa julgada (CPP, art. 65).","",["Muda.","Correta.","Não gera indenização.","Tem efeito.","Não precisa provar de novo."]],"116ggez":["Exercício regular de direito.","",["O dever é só da polícia.","Correta.","Não há perigo.","Não necessariamente há agressão.","O fato é lícito."]],"zkamfe":["Disponível e o ofendido é capaz.","",["Bem indisponível não admite.","Correta.","A vida é indisponível.","Bem coletivo não admite.","Bem público não admite."]],"z5hd3d":["Moderado dos meios necessários (art. 25).","",["Não qualquer meio.","Correta.","Não só armas.","Não só as mãos.","Força máxima é excesso."]],"1llgeq3":["A título de dolo ou culpa, conforme o caso.","",["É punido.","Correta.","Não sempre qualificado.","Não gera perdão judicial.","Não só multa."]],"1xejs7f":["Não está escrito no CP, mas é aceito pela doutrina e jurisprudência, desde que o bem seja disponível e o ofendido capaz.",""],"ercrvh":["Sem agressão humana, não há legítima defesa. O ataque espontâneo do animal gera estado de necessidade.",""]},"pessoa-patrimonio":{"1ka6prv":["É a Súmula 610 do STF: no latrocínio, o que define a consumação é a MORTE. Se a vítima morre, há latrocínio consumado, mesmo que nada tenha sido levado.","Morte consumada + subtração tentada = latrocínio consumado. Morte tentada + subtração consumada = latrocínio tentado."],"ntc0gg":["Desde a Lei 13.654/2018, a arma de fogo aumenta a pena de 2/3 (art. 157, §2º-A, I). O aumento de 1/3 até a metade (§2º) vale para outras hipóteses, como arma branca, concurso de pessoas e restrição da liberdade da vítima.",""],"1hzfz0g":["É o art. 121, caput, do CP.",""],"u1wtbx":["O homicídio qualificado (art. 121, §2º) tem pena de 12 a 30 anos. 6 a 20 é o homicídio simples.",""],"m062z5":["A Lei 14.994/2024 (“pacote antifeminicídio”) tirou o feminicídio do rol de qualificadoras e criou o art. 121-A: matar mulher por razões da condição do sexo feminino (violência doméstica ou menosprezo/discriminação à condição de mulher).",""],"r86at8":["O feminicídio (art. 121-A) tem pena de 20 a 40 anos, maior que a do homicídio qualificado (12 a 30).",""],"oa14y4":["É o art. 121, §1º: relevante valor social ou moral, ou domínio de violenta emoção logo após injusta provocação da vítima. A pena é reduzida de 1/6 a 1/3.",""],"10r2cy5":["É o art. 121, §3º. No trânsito, o homicídio culposo tem tipo próprio no CTB (art. 302), com pena de detenção de 2 a 4 anos.",""],"1ts8zq7":["É o perdão judicial (art. 121, §5º): exemplo clássico é o pai que, por descuido, causa a morte do próprio filho. A sentença que concede o perdão extingue a punibilidade e não gera reincidência (Súmula 18 do STJ).",""],"19i651f":["O infanticídio (art. 123) é crime próprio: só a MÃE, sob a influência do estado puerperal, matando o próprio filho durante o parto ou logo após. Fora disso, é homicídio.",""],"9yxwjb":["É o aborto necessário ou terapêutico (art. 128, I): não exige consentimento da gestante nem autorização judicial.",""],"1vkzlkl":["É o aborto humanitário ou sentimental (art. 128, II): exige consentimento da gestante ou do representante legal, sem necessidade de autorização judicial. O STF também admite a interrupção da gestação de feto anencéfalo (ADPF 54).",""],"6w9j9u":["É lesão GRAVE (art. 129, §1º, I). As gravíssimas (§2º) são: incapacidade permanente para o trabalho, enfermidade incurável, perda ou inutilização de membro, sentido ou função, deformidade permanente e aborto.","Grave (§1º): 30 dias, perigo de vida, debilidade, aceleração de parto. Gravíssima (§2º): permanente, incurável, perda, deformidade, aborto."],"1a7vwdc":["É o art. 129, §2º, III. A mera debilidade permanente (diminuição) é lesão grave (§1º, III).",""],"mobrp4":["É o art. 129, §2º, V. O agente precisa saber que a vítima está grávida, e o aborto é resultado culposo (não desejado).",""],"m9vmm0":["Aceleração de parto é lesão GRAVE (art. 129, §1º, IV): o bebê nasce antes do tempo, mas vivo. Se morre (aborto), a lesão é gravíssima.",""],"14fs9g5":["É o art. 129, §3º: o agente quer só lesionar (dolo), mas a vítima morre por um resultado que ele não quis nem assumiu (culpa). Pena de 4 a 12 anos, julgada pelo juiz singular, e não pelo Júri.",""],"196xril":["É o art. 135, parágrafo único: aumenta de metade se resulta lesão grave e triplica se resulta morte. No trânsito, a omissão do condutor envolvido tem tipo próprio (CTB, art. 304).",""],"l1bcvg":["É o art. 138 do CP: atribuir a alguém um CRIME que ele não cometeu. Admite exceção da verdade, em regra.","Calúnia = crime falso. Difamação = fato ofensivo (verdadeiro ou não). Injúria = xingamento, sem fato."],"1okf9vo":["Esse é o crime de DIFAMAÇÃO (art. 139): o fato é ofensivo, mas não é crime, e pode até ser verdadeiro. Exemplo: dizer que o vizinho chega bêbado em casa toda noite.",""],"1gt0l9o":["É o art. 140 do CP: atribuir qualidade negativa, como chamar alguém de ladrão sem citar um fato concreto. A injúria com elementos de raça, cor, etnia ou origem passou a ser racismo (Lei 14.532/2023).",""],"4kruxs":["A injúria não admite exceção da verdade, porque não há fato a provar. Admitem: a calúnia (com exceções) e a difamação contra funcionário público em razão das funções.",""],"qczsmu":["É o art. 139, parágrafo único: só nesse caso, porque interessa à sociedade saber se o servidor age mal no cargo.",""],"16kj7bg":["É o art. 147-A (Lei 14.132/2021): perseguir alguém repetidamente, por qualquer meio, ameaçando sua integridade, restringindo sua locomoção ou invadindo sua privacidade. A ação é pública condicionada à representação.",""],"1yxriii":["É o art. 147-B (Lei 14.188/2021): violência psicológica contra a mulher, por ameaça, humilhação, manipulação, isolamento, chantagem ou outros meios.",""],"1li52za":["É o art. 155 do CP: sem violência ou grave ameaça. Pena de 1 a 4 anos e multa.",""],"4y3p3t":["É o art. 155, §1º. O STJ admite o aumento mesmo em estabelecimento comercial e também no furto qualificado.",""],"1dbvrd4":["É o art. 155, §3º: o “gato” de energia é furto.",""],"eh10un":["Escalada e rompimento de obstáculo são QUALIFICADORAS (art. 155, §4º), com pena de 2 a 8 anos. O privilegiado é o do §2º (primário e coisa de pequeno valor).",""],"g1jley":["É o art. 155, §2º: o juiz pode trocar a reclusão por detenção, diminuir a pena de 1/3 a 2/3 ou aplicar só multa. Pequeno valor é o que não passa de um salário mínimo, segundo a jurisprudência. O privilégio é compatível com a qualificadora objetiva (Súmula 511 do STJ).",""],"1azblmn":["Câmeras e seguranças dificultam o furto, mas não o tornam impossível. Por isso há tentativa, e não crime impossível.",""],"1yma9mw":["É o art. 157, §1º: o agente pega a coisa sem violência e, para fugir ou ficar com ela, emprega violência logo em seguida.",""],"16c2cvp":["Teoria da amotio (ou apprehensio): basta o bem sair da esfera da vítima e passar para o agente, mesmo por pouco tempo e mesmo que ele seja perseguido e preso logo depois.",""],"11trhtq":["É o art. 157, §2º-A, I.",""],"18xqgvy":["Com arma de uso restrito ou proibido, a pena é aplicada em DOBRO (art. 157, §2º-B, incluído pelo Pacote Anticrime).","Arma branca = +1/3 a 1/2. Arma de fogo = +2/3. Arma de uso restrito ou proibido = em dobro."],"rrb615":["É o art. 157, §3º, II, e é hediondo (Lei 8.072/1990). É crime contra o patrimônio, e por isso é julgado pelo juiz singular, e não pelo Júri (Súmula 603 do STF).",""],"12n1zz3":["É o art. 158, §3º: o agente prende a vítima para obrigá-la a entregar algo (como sacar dinheiro no caixa eletrônico). A pena é de 6 a 12 anos.",""],"t6dne6":["É o art. 159 do CP e a Lei 8.072/1990, em todas as formas.",""],"17bh2am":["É a delação premiada do art. 159, §4º: se a delação facilitar a libertação do sequestrado, a pena do delator é reduzida de 1/3 a 2/3.",""],"k908wr":["É o art. 171, §5º (Pacote Anticrime). As exceções (ação incondicionada) são quando a vítima é a Administração Pública, criança ou adolescente, pessoa com deficiência mental, maior de 70 anos ou incapaz.",""],"1f404f1":["Com vítima maior de 70 anos, a ação é pública INCONDICIONADA (art. 171, §5º, IV).",""],"b89uby":["É a Súmula 17 do STJ: se o documento falso foi usado só para o golpe e não serve para mais nada, o estelionato absorve a falsificação (consunção).",""],"g7iio1":["É o art. 180, §4º: basta provar que a coisa veio de crime. Não é preciso identificar ou punir o ladrão.",""],"hri72m":["É o art. 180, §3º: adquirir coisa que, pela natureza, pela desproporção entre valor e preço ou pela condição de quem oferece, deveria fazer presumir que veio de crime. Exemplo: celular novo vendido a preço muito baixo na rua.",""],"1qc8hcn":["As escusas do art. 181 (cônjuge, ascendente, descendente) não se aplicam a roubo, extorsão ou qualquer crime com violência ou grave ameaça (art. 183, I).",""],"1ru885l":["O art. 183, III, exclui as escusas quando a vítima tem 60 anos ou mais. A proteção ao idoso prevalece.",""],"d2klpn":["Qualificado (art. 121, §2º, II).","",["A qualificadora afasta a forma simples.","Privilegiado é motivo de relevante valor.","Correta.","Há dolo.","Preterdoloso é dolo na lesão e culpa na morte."]],"1wq8s4n":["Infanticídio (art. 123).","",["O estado puerperal gera crime próprio, mais brando.","Correta.","Aborto é antes do parto.","Há dolo.","Não é abandono."]],"1eomytm":["Calúnia (art. 138).","",["Injúria não imputa fato.","Difamação imputa fato não criminoso.","Correta.","Ameaça é prometer mal grave.","Denunciação caluniosa exige provocar investigação ou processo."]],"im13ei":["Roubo (art. 157).","",["Furto não tem violência.","Correta.","Na extorsão, a vítima entrega o bem.","Estelionato é fraude.","Apropriação é de coisa que já estava com o agente."]],"1s2j99":["Estelionato (art. 171).","",["No furto mediante fraude, a fraude distrai a vítima para subtrair; no estelionato, a vítima entrega.","Correta.","Roubo tem violência.","Receptação é adquirir produto de crime.","Extorsão tem violência ou ameaça."]],"1n5svlz":["Receptação (art. 180).","",["Favorecimento real é ajudar o criminoso a guardar o proveito, sem proveito próprio.","Correta.","Não é subtração.","Não é apropriação.","Não é fraude."]],"1hmk92f":["20 a 30 anos (art. 157, §3º, II).","",["É o homicídio simples.","É o homicídio qualificado.","Correta.","É o feminicídio.","Não é o latrocínio."]],"xseed5":["2 a 8 anos.","",["É o furto simples.","Correta.","Não é o prazo.","4 a 10 anos é o furto com emprego de explosivo (§4º-A).","Não é o prazo."]],"1nf38iu":["Deformidade permanente (art. 129, §2º, IV).","",["Perigo de vida é grave.","Aceleração de parto é grave.","Correta.","Incapacidade por mais de 30 dias é grave.","Debilidade é grave."]],"1t2h8yf":["Consuma-se independentemente da obtenção da vantagem indevida.","",["É formal.","Correta.","Não exige.","Admite tentativa (por exemplo, ameaça por carta interceptada).","Só a extorsão mediante sequestro e a qualificada pela morte são hediondas."]],"ry2uwo":["Injúria (art. 140).","",["Calúnia imputa crime.","Difamação imputa fato.","Correta.","Ameaça promete mal.","Constrangimento obriga a fazer ou não fazer."]],"1qrte9f":["Detenção de 1 a 3 anos (art. 121, §3º).","",["É detenção, e não reclusão.","Correta.","Não é o prazo.","É o homicídio simples.","É o homicídio culposo do CTB."]],"1sfa9q2":["Repouso noturno: é causa de aumento (§1º).","",["É qualificadora.","É qualificadora.","É qualificadora.","Correta.","É qualificadora."]],"11kr0eo":["Aborto humanitário, não punível (art. 128, II).","",["Não é punível.","Correta.","Necessário é para salvar a vida da gestante.","Infanticídio é após o parto.","Não é lesão."]],"16vz4ep":["É a Súmula 582 do STJ.",""],"14vkxok":["É o art. 121, §2º, VII: homicídio contra integrantes das Forças Armadas e das forças de segurança pública (art. 144 da CF), no exercício da função ou em razão dela, e contra seus parentes até o 3º grau por esse motivo. É hediondo.",""],"w79skp":["É a Súmula 443 do STJ: não basta contar quantas majorantes existem; o juiz deve explicar, com base no caso, por que aplica um aumento maior.",""]},"principios":{"hszpxx":["É o art. 62, §1º, I, b, da CF: MP não pode tratar de direito penal. Crime e pena só podem ser criados por lei em sentido estrito, aprovada pelo Congresso (reserva legal). O STF admite MP que beneficia o réu, mas nunca para incriminar.",""],"1cgf3o2":["A Súmula 599 do STJ afasta a insignificância nesses crimes, porque, além do patrimônio, protege-se a moralidade administrativa. A exceção aceita é o descaminho.",""],"1dqyhgj":["É o art. 1º do CP e o art. 5º, XXXIX, da CF: princípio da legalidade, que reúne a reserva legal (só lei) e a anterioridade (lei anterior ao fato).",""],"12otuqh":["Só lei ordinária ou complementar aprovada pelo Congresso. Decreto, portaria, resolução e MP não criam crimes.",""],"xrxq1k":["É vedado pelo art. 62, §1º, I, b, da CF, mesmo com urgência.",""],"cka2co":["É o art. 1º do CP: só se pune o fato se, quando praticado, já havia lei definindo-o como crime.",""],"1vgxdh9":["Lei vaga (“praticar atos contra os bons costumes”) viola a legalidade, porque o cidadão não sabe o que é proibido. É a exigência de lei certa (lex certa).",""],"i00wn4":["É o art. 5º, XL, da CF: a lei mais grave não alcança o passado; a mais benéfica alcança, até depois do trânsito em julgado.",""],"19pwtrp":["O Direito Penal é a ultima ratio (último recurso). Desdobra-se em fragmentariedade e subsidiariedade.",""],"gb10y6":["O Direito Penal cuida só de “fragmentos”: os bens mais importantes contra os ataques mais graves.",""],"5yddkh":["Só se recorre ao Direito Penal se o civil e o administrativo não resolverem.",""],"rregmy":["Não basta a conduta ser imoral ou desagradável: tem que lesar ou ameaçar um bem jurídico de alguém.",""],"1xqg72i":["A conduta se encaixa no texto da lei (tipicidade formal), mas a lesão é tão pequena que não ofende de verdade o bem jurídico (falta tipicidade material). O fato é atípico.",""],"1j5ydmt":["São os quatro vetores fixados pelo STF (HC 84.412). Macete “MARI”: Mínima ofensividade, Ausência de periculosidade social, Reduzido grau de reprovabilidade, Inexpressividade da lesão.",""],"14r4vyx":["É a Súmula 599 do STJ.",""],"1jmvud4":["É a Súmula 589 do STJ: a violência doméstica nunca é considerada irrelevante.",""],"1s3axnd":["Ninguém é punido sem dolo ou culpa (nullum crimen sine culpa). Responder só porque o resultado aconteceu, sem dolo ou culpa, é proibido.",""],"gb8x6o":["É o art. 5º, XLV, da CF: se o condenado morre, a pena se extingue, e os filhos não cumprem pena no lugar dele.",""],"1dym7bv":["É o art. 5º, XLV, da CF: a pena não passa, mas a obrigação civil de indenizar e o perdimento podem alcançar os herdeiros, até o valor da herança.",""],"12hewy":["É o art. 5º, XLVI, da CF: a pena é individualizada em três momentos: pelo legislador (cominação), pelo juiz (aplicação) e na execução.",""],"fjt8b9":["É o art. 5º, XLVII, da CF: proíbe penas de morte (salvo guerra declarada), de caráter perpétuo, de trabalhos forçados, de banimento e cruéis.",""],"f69jx7":["A pena não pode ser exagerada (proibição do excesso) nem insuficiente para proteger o bem (proibição da proteção deficiente).",""],"i6gxn0":["O Direito Penal só intervém quando há ofensa a bem de terceiro. Por isso a autolesão e a tentativa de suicídio não são punidas.",""],"1q0g6w2":["Condutas aceitas pela sociedade não devem ser crime, mesmo que se encaixem no texto da lei. Exemplo: furar a orelha de uma criança para pôr brinco.",""],"1vb04p4":["Ninguém pode ser processado ou punido duas vezes pelo mesmo fato, nem ter a mesma circunstância usada duas vezes contra si na dosimetria.",""],"19p582x":["Usar a analogia para prejudicar o réu (criar crime ou aumentar pena) viola a legalidade.",""],"19uxs52":["Usar a analogia a favor do réu é permitido, desde que haja lacuna na lei.",""],"146kesb":["É vedado pela legalidade.",""],"1l2726c":["A lei traz a pena, mas parte da conduta precisa ser completada por outra norma. Homogênea: o complemento é outra lei. Heterogênea: o complemento é ato administrativo.",""],"hg59of":["A Lei 11.343/2006 pune o tráfico de “drogas”, mas quem diz quais substâncias são drogas é a Portaria SVS/MS 344/1998 da Anvisa (ato administrativo).",""],"8c2dnb":["O Direito Penal não pune pecados ou opiniões, só condutas que atingem bens jurídicos.",""],"8et6i":["Roubo envolve violência ou grave ameaça, e isso afasta a mínima ofensividade, mesmo que o bem tenha valor baixo.",""],"1fwe0by":["O STF decidiu que a reincidência, sozinha, não impede automaticamente a insignificância. O juiz analisa o caso concreto.",""],"1o28q96":["O bem protegido é a fé pública (a confiança no dinheiro), que é ofendida mesmo com uma única cédula de valor baixo.",""],"yyjnbd":["Intranscendência (pessoalidade).","",["Legalidade é sobre lei anterior.","Correta.","Insignificância é sobre lesão mínima.","Adequação social é conduta aceita.","Alteridade é lesão a terceiro."]],"64pvnj":["Administração Pública.","",["Não é essa a súmula.","Correta.","Não trata de honra.","Não trata de liberdade.","O furto admite insignificância."]],"1iee277":["Taxatividade.","",["Anterioridade é lei prévia.","Correta.","Alteridade é lesão a terceiro.","Subsidiariedade é último recurso.","Humanidade veda penas cruéis."]],"b5syu7":["A condição econômica da vítima não é vetor fixo.","",["É vetor.","É vetor.","É vetor.","É vetor.","Correta."]],"q4gw4g":["Retroage para beneficiar o réu.","",["Retroage.","Correta.","Vale para o passado.","Não depende de vontade.","Retroage até depois do trânsito em julgado."]],"249kmf":["Apenas em favor do réu.","",["Não sempre.","Correta.","Contra o réu é proibida.","É admitida a favor.","Não depende da gravidade."]],"sgi5od":["Em branco heterogênea.","",["Precisa de complemento.","Correta.","Homogênea é complementada por lei.","Não é permissiva.","Não é explicativa."]],"16jmgq":["Intervenção mínima.","",["Correta.","Taxatividade é clareza da lei.","Anterioridade é lei prévia.","Individualização é pena sob medida.","Pessoalidade é pena só ao condenado."]],"1gwftsi":["Culpabilidade.","",["Correta.","Legalidade é sobre lei.","Humanidade veda penas cruéis.","Anterioridade é lei prévia.","Lesividade é ofensa ao bem jurídico."]],"7ibx73":["Lei em sentido estrito.","",["MP é vedada.","Correta.","Decreto não pode.","Resolução não pode.","Portaria não pode (só complementar norma em branco)."]],"1k2077u":["Contra a mulher no âmbito doméstico.","",["Não é essa súmula.","Correta.","Furto admite.","É outra regra.","Não é essa súmula."]],"vis2xu":["Alteridade.","",["Correta.","Anterioridade é lei prévia.","Taxatividade é clareza.","Proporcionalidade é equilíbrio da pena.","Legalidade é lei."]],"ttrqpg":["Em caso de guerra declarada (art. 5º, XLVII, a).","",["Há a exceção da guerra.","Correta.","Não para hediondos.","Não para tráfico.","Não para terrorismo."]],"h4sf25":["Adequação social.","",["Não é sobre valor da lesão.","Correta.","A lesão é em terceiro.","Há lesão física, mas aceita.","Não é sobre pena."]],"17q4pw9":["Ne bis in idem.","",["Correta.","In dubio pro reo é na dúvida, absolver.","Nemo tenetur é não se autoincriminar.","Tempus regit actum é lei processual no tempo.","Nullum crimen é legalidade."]],"rwzzeu":["Tipicidade material.","",["Não é excludente de ilicitude.","Não é excludente de culpabilidade.","Correta.","Exclui antes, a tipicidade.","Não tem relação."]],"jcgyql":["Crimes com violência ou grave ameaça afastam a insignificância, qualquer que seja o valor.",""],"y4ebh5":["O Direito Penal só intervém quando há lesão a bem jurídico de outra pessoa.",""],"1y10soa":["É a Súmula 589 do STJ.",""]},"sexual-incolumidade":{"2yj8xv":["É a Súmula 593 do STJ e o art. 217-A, §5º: com menor de 14 anos, o crime existe mesmo com consentimento, experiência sexual anterior ou relacionamento amoroso com o agente. A lei presume a vulnerabilidade de forma absoluta.",""],"5wk94j":["Desde a Lei 13.718/2018, o art. 225 do CP prevê ação pública INCONDICIONADA para todos os crimes contra a liberdade sexual e contra vulnerável. O MP age sem depender da vítima.",""],"72clhz":["É o art. 213 do CP: desde 2009, o estupro abrange a conjunção carnal e qualquer outro ato libidinoso, e qualquer pessoa pode ser autora ou vítima.",""],"1l95kew":["É o art. 213, caput.",""],"p71fgc":["Desde a Lei 12.015/2009, a vítima é “alguém”: homem ou mulher.",""],"ru1ta8":["É o art. 213, §1º: 8 a 12 anos.",""],"zgfib":["É o art. 213, §2º.",""],"xm98oh":["É o art. 217-A. Se resulta lesão grave: 10 a 20 anos; se resulta morte: 12 a 30 anos.",""],"i3f8e2":["É o art. 217-A: não é preciso violência ou ameaça. A idade da vítima basta.",""],"r6xgy8":["O consentimento é irrelevante (art. 217-A, §5º, e Súmula 593 do STJ).",""],"2f03r6":["É o art. 217-A, §1º: inclui também quem não pode oferecer resistência, como a pessoa desacordada ou completamente embriagada.",""],"xhyn2t":["É o art. 215-A (Lei 13.718/2018): exemplo é o ato libidinoso no transporte público. Pena de 1 a 5 anos, se o ato não constitui crime mais grave.",""],"5sz4nv":["Não exige. Se houver violência ou grave ameaça, o crime é estupro.","Sem violência = importunação sexual. Com violência ou grave ameaça = estupro."],"4g4ocj":["É o art. 216-A: o agente usa a posição de chefe ou a ascendência da função para constranger alguém a ter vantagem sexual. Sem essa relação de trabalho, não há assédio sexual.",""],"7qdzxm":["É o art. 216-A. A pena aumenta em até 1/3 se a vítima é menor de 18 anos (§2º).",""],"k010b":["É o art. 215 (violação sexual mediante fraude): por exemplo, o falso médico que engana a paciente. Pena de 2 a 6 anos.",""],"12bnsqt":["É o art. 216-B (Lei 13.772/2018): registro não autorizado da intimidade sexual. Pena de 6 meses a 1 ano e multa.",""],"v9y07o":["É o art. 218-C: também pune divulgar cena de sexo ou nudez sem consentimento da vítima. A pena aumenta se o agente tinha relação íntima com a vítima ou agiu por vingança.",""],"15yf5oq":["É o art. 225 do CP (Lei 13.718/2018).",""],"1fvxhv8":["A ação é pública incondicionada (art. 225). A regra antiga de ação privada foi abandonada há muito tempo.",""],"73l1hi":["É o art. 234-B do CP: para proteger a intimidade da vítima.",""],"cb0uba":["É o art. 1º, V e VI, da Lei 8.072/1990, em todas as formas.",""],"4lgb4e":["É o art. 230 do CP (rufianismo). A prostituição em si não é crime no Brasil; pune-se quem explora.",""],"1sp4yqr":["É o art. 233 do CP: pena de 3 meses a 1 ano ou multa. É crime de menor potencial ofensivo.",""],"1pbqou":["Título VIII do CP: o perigo alcança um número indeterminado de pessoas (exemplo: incêndio, explosão, epidemia).",""],"1gsdzcp":["É o art. 250 do CP: reclusão de 3 a 6 anos e multa.",""],"dvp8s7":["É o art. 250, §2º: detenção de 6 meses a 2 anos.",""],"c3ouo5":["É crime de PERIGO concreto: basta expor a perigo a vida, a integridade ou o patrimônio de outra pessoa. Não precisa causar dano.",""],"1rfykd7":["É o art. 250, §1º, II, a. Também aumenta em edifício público, embarcação, estação ferroviária, lavoura, mata, entre outros.",""],"prbb67":["É o art. 264 do CP: pedra em ônibus ou trem em movimento, por exemplo.",""],"11d3u3s":["É o art. 267 do CP: reclusão de 10 a 15 anos. Com resultado morte, é hediondo.",""],"30pzsg":["É o art. 267, §1º.",""],"u44ki3":["É o art. 268 do CP (infração de medida sanitária preventiva), muito discutido durante a pandemia. É norma penal em branco.",""],"u6sfh5":["É o art. 269 do CP (omissão de notificação de doença): crime próprio do médico.",""],"181nkv4":["É o art. 283 do CP. Pode ser praticado por qualquer pessoa, inclusive médico.",""],"t3yyik":["São crimes diferentes. Charlatanismo (art. 283): anunciar cura secreta ou infalível. Curandeirismo (art. 284): prescrever ou ministrar substância, usar gestos ou palavras, ou fazer diagnósticos, sem ser médico.",""],"1szec8l":["É o art. 282 do CP: também vale para dentista e farmacêutico, ou para quem excede os limites da profissão. Se houver lucro, aplica-se também multa.",""],"d48u0h":["É o art. 270 do CP.",""],"1t26fds":["Importunação sexual (art. 215-A).","",["Estupro exige violência ou grave ameaça.","Correta.","Assédio exige relação de trabalho.","Ato obsceno não é contra alguém determinado.","A fraude não está descrita."]],"4hr2ju":["8 a 15 anos (art. 217-A).","",["É o estupro simples.","É o estupro com lesão grave ou vítima de 14 a 18 anos.","Correta.","É com resultado morte.","É a violação sexual mediante fraude."]],"1ijsekw":["Pública incondicionada (art. 225).","",["Não é privada.","Era a regra antes de 2018.","Correta.","Só cabe com inércia do MP.","Não depende de requisição."]],"7c96qf":["Assédio sexual (art. 216-A).","",["Importunação é ato libidinoso sem anuência.","Correta.","Estupro exige violência ou ameaça.","Rufianismo é explorar prostituição.","Perseguição é o stalking."]],"1fwqxfo":["Menor de 14 anos (art. 217-A).","",["Não é o limite.","Correta.","Não é o limite.","Menor de 18 é qualificadora do estupro simples.","Não é o limite."]],"wea18y":["12 a 30 anos (art. 213, §2º).","",["É o estupro simples.","É com lesão grave.","Correta.","É o latrocínio.","É o feminicídio."]],"bt8068":["Perigo comum.","",["Atingem número indeterminado de pessoas.","Correta.","Não são de mão própria.","A ação é pública.","Nem todos são de menor potencial."]],"1b1wu71":["10 a 15 anos (art. 267).","",["É o incêndio.","Correta.","Não é o prazo.","Não é o prazo.","Não é o prazo."]],"qw41fm":["Charlatanismo (art. 283).","",["Curandeirismo é prescrever ou ministrar.","Correta.","Exercício ilegal é atuar como médico sem habilitação.","Não é estelionato.","Não é falsidade."]],"1kdjf7y":["Rufianismo (art. 230).","",["Favorecimento é induzir ou facilitar a prostituição.","Correta.","Casa de prostituição é manter local.","Mediação é induzir alguém a satisfazer outrem.","Ato obsceno é outro crime."]],"a2eim":["Reclusão de 3 a 6 anos e multa (art. 250).","",["Não é o prazo.","Correta.","É a epidemia.","Não é o prazo.","É o incêndio culposo."]],"2tvd2g":["218-C.","",["É o estupro.","É a importunação sexual.","É o assédio sexual.","Correta.","É o ato obsceno."]],"143n1gp":["Omissão de notificação de doença (art. 269).","",["Prevaricação é crime funcional por interesse pessoal.","Correta.","Infração de medida sanitária é o art. 268.","Charlatanismo é anunciar cura.","Condescendência é não punir subordinado."]],"lpwzo6":["Estupro e estupro de vulnerável.","",["Não são hediondos.","Correta.","Não são hediondos.","O assédio não é hediondo.","Não é hediondo."]],"hqjqny":["O art. 213 abrange conjunção carnal OU outro ato libidinoso. Qualquer um deles consuma o crime.",""]},"tipicidade":{"1wex2d":["É o art. 15 do CP: o agente começa a execução e, podendo continuar, desiste por vontade própria. Não há tentativa do crime que pretendia; ele responde só pelo que já fez. Exemplo: quem dá um tiro, podia dar outros e para, responde por lesão, e não por tentativa de homicídio.","Desistência = para no meio da execução. Arrependimento eficaz = termina a execução e depois impede o resultado."],"1utjd8h":["Pelo art. 20 do CP, todo erro de tipo exclui o dolo. Se for INEVITÁVEL, exclui também a culpa. Se for EVITÁVEL, o agente responde por crime culposo, se houver previsão legal.",""],"1b9ghpv":["É o art. 13 do CP: só responde pelo resultado quem o causou.",""],"nley08":["É a teoria da equivalência dos antecedentes (conditio sine qua non), do art. 13: tudo o que, se retirado mentalmente, faria o resultado não acontecer é causa. Os excessos dessa teoria são limitados pelo dolo e pela culpa.",""],"13j7xy4":["É o art. 13, §1º: exemplo clássico é a vítima ferida que morre no incêndio do hospital. O agente responde só pela tentativa (ou pela lesão), porque o incêndio, sozinho, produziu a morte.",""],"1feqoc":["É o art. 13, §2º: são os crimes omissivos impróprios (comissivos por omissão). Quem tem o dever de agir (garante) responde pelo resultado como se o tivesse causado.",""],"kmttog":["É o art. 13, §2º, a: pais em relação aos filhos, policiais, bombeiros.",""],"1u9iabn":["É o art. 13, §2º, b: babá, salva-vidas contratado, guia de montanhismo.",""],"2q6tfp":["É o art. 13, §2º, c (ingerência): quem empurra alguém na piscina, por brincadeira, deve salvá-lo se ele não souber nadar.","Garante (art. 13, §2º): a) dever legal; b) assumiu a responsabilidade; c) criou o risco."],"w864ct":["É o art. 14, I, do CP.",""],"fbkdwq":["É o art. 14, II: há início da execução e a consumação não ocorre por motivo alheio à vontade do agente (exemplo: a polícia chega).",""],"1thkcyv":["É o art. 14, parágrafo único: quanto mais perto da consumação, menor a redução. Há exceções, como crimes de atentado, em que a tentativa tem a mesma pena.",""],"woh47d":["É o caminho do crime. Alguns autores incluem o exaurimento (efeitos posteriores à consumação).",""],"128jygc":["Pensar não é crime. Os atos preparatórios só são punidos quando a lei os transforma em crime autônomo (por exemplo, associação criminosa, petrechos para falsificação).",""],"r884bf":["É o art. 15 do CP.",""],"1ow83bs":["É o art. 15: o agente esgota a execução, mas age para evitar o resultado (exemplo: envenena e depois dá o antídoto). Só responde pelo que já causou.",""],"m9pao7":["É o art. 16: o crime já se consumou, mas o agente repara o dano ou devolve a coisa, voluntariamente, até o RECEBIMENTO da denúncia. A pena cai de 1/3 a 2/3.",""],"oze3op":["É o crime impossível (art. 17): exemplo de meio ineficaz é a arma de brinquedo; de objeto impróprio, tentar matar quem já está morto. Se a ineficácia for só relativa, há tentativa.",""],"viwhqv":["É o art. 18, I: dolo direto (quis) e dolo eventual (assumiu o risco).",""],"1ss3d61":["É o art. 18, II. Imprudência: fazer algo perigoso (dirigir em alta velocidade). Negligência: deixar de tomar um cuidado (não revisar o freio). Imperícia: falta de habilidade técnica na profissão.",""],"wpvrgi":["É o art. 18, parágrafo único: a forma culposa só existe quando a lei a prevê expressamente. Por exemplo, não existe furto culposo.",""],"16ynvmn":["O agente pensa: “se acontecer, tanto faz”. É dolo, e não culpa.",""],"1qhxudb":["O agente pensa: “pode acontecer, mas eu consigo evitar”. É culpa.","Dolo eventual = “tanto faz”. Culpa consciente = “não vai acontecer”."],"y05paj":["É o art. 19 do CP: impede a responsabilidade objetiva. Exemplo: na lesão corporal seguida de morte, a morte precisa ter sido ao menos previsível.",""],"qj31e7":["É o art. 20 do CP (erro de tipo): exemplo é quem leva o guarda-chuva de outra pessoa achando que é o seu. Não sabe que a coisa é “alheia”, e por isso não há dolo de furto.",""],"1eqk6lu":["Se nenhuma pessoa cuidadosa evitaria o erro, não há dolo nem culpa. O fato é atípico.",""],"wagbgy":["É o art. 20, §3º: quem quer matar o pai e, por engano, mata um estranho, responde como se tivesse matado o pai (com a agravante de ascendente).",""],"19qmayc":["É o art. 20, §1º (descriminante putativa por erro de tipo): exemplo é a legítima defesa putativa. Se o erro decorre de culpa, responde por crime culposo.",""],"bunsko":["É o art. 20, §2º: quem engana outra pessoa para que ela cometa o crime sem saber responde como autor (autoria mediata).",""],"6dd51d":["A regra é a redução de 1/3 a 2/3 (art. 14, parágrafo único), salvo disposição em contrário.",""],"1hpq1y8":["O limite é o recebimento da denúncia ou queixa (art. 16). Depois disso, a reparação é só atenuante (art. 65, III, b).",""],"144k5rn":["O crime formal descreve um resultado, mas não exige que ele ocorra. Exemplo: a extorsão se consuma com o constrangimento, mesmo sem a vítima pagar (Súmula 96 do STJ).",""],"144477y":["A lei descreve só a conduta, sem nenhum resultado. Exemplo: violação de domicílio, porte ilegal de arma.","Material = exige resultado. Formal = prevê, mas não exige. Mera conduta = não prevê resultado."],"1dih6d6":["Culposo: não há vontade de chegar ao resultado. Contravenção: a tentativa não é punida (LCP, art. 4º). Omissivo próprio: ou se omite (consuma) ou age (não há crime).",""],"ice4pq":["Equivalência dos antecedentes (art. 13).","",["Causalidade adequada é usada na exceção do §1º.","Correta.","Imputação objetiva é teoria doutrinária, não adotada como regra no CP.","Não é a regra.","Tipicidade conglobante é teoria de Zaffaroni sobre o tipo."]],"kgwg5g":["1/3 a 2/3 (art. 14).","",["1/6 a 1/3 é o erro de proibição evitável.","Correta.","Não é metade.","Não é o prazo.","É punida."]],"8g5nv3":["Arrependimento eficaz (art. 15).","",["Na desistência, ele para antes de terminar a execução.","Correta.","Posterior é depois da consumação, com reparação do dano.","O meio era eficaz.","O resultado foi evitado pela vontade dele."]],"141zhio":["Desistência voluntária (art. 15).","",["Correta.","No arrependimento, ele já tinha terminado a execução.","Posterior é após a consumação.","O meio era eficaz.","Não houve circunstância alheia."]],"1n1f5en":["O recebimento da denúncia (art. 16).","",["Pode ser depois do inquérito.","Correta.","Até a sentença é só atenuante.","Não é o limite.","Não é o limite."]],"1y0qt16":["Crime impossível por ineficácia absoluta do meio (art. 17).","",["Não há tentativa punível.","Correta.","Não houve morte.","Não houve arrependimento.","Não houve desistência."]],"8cfi57":["Dolo eventual (art. 18, I).","",["Na culpa consciente, ele acredita que não vai acontecer.","Correta.","Na culpa inconsciente, ele nem prevê.","Dolo de 2º grau é a consequência necessária do meio escolhido.","Preterdolo é dolo no antecedente e culpa no resultado."]],"atersl":["Culpa consciente.","",["No dolo eventual, ele assume o risco.","Correta.","No dolo direto, ele quer.","Na inconsciente, ele não prevê.","Erro de proibição é sobre a ilicitude."]],"rzoc4d":["Imprudência, negligência e imperícia (art. 18, II).","",["Não são modalidades de culpa.","Correta.","São formas de conduta.","São fases do crime.","Não são modalidades."]],"176pxhg":["Exclui o dolo, permitindo punição por culpa, se prevista (art. 20).","",["Isso é o invencível.","Correta.","É relevante.","Exclui o dolo, e não a culpabilidade.","Não agrava."]],"5cxg2j":["Vítima que o agente pretendia atingir (art. 20, §3º).","",["Não da vítima atingida.","Correta.","Não tem relação.","Não tem relação.","Não tem relação."]],"32634d":["Crime culposo.","",["Admite.","Admite.","Correta.","Admite.","Admite."]],"1a4i9ny":["Tinha dever legal de cuidado e podia agir (art. 13, §2º, a).","",["Tinha o dever.","Correta.","Pode ser dolo ou culpa, conforme o caso.","É omissivo impróprio.","Há crime."]],"ghbjfi":["Formal (Súmula 96 do STJ).","",["Material exigiria a vantagem.","Correta.","A lei prevê resultado.","É doloso.","Não exige reiteração."]],"m0q45c":["Ao menos culposamente (art. 19).","",["Também por culpa.","Correta.","Não há responsabilidade objetiva.","Responde.","Não depende de confissão."]],"ibe4bt":["Na culpa, o agente não quer o resultado; sem vontade dirigida a ele, não há como “tentar”.",""],"eqow5k":["Na desistência voluntária não há tentativa: o agente responde apenas pelos atos já praticados (art. 15).",""],"kisrrq":["É a Súmula 567 do STJ: a vigilância, por si só, não torna o crime impossível. Há tentativa de furto.",""]}};
